#
# Regenerates the checked-in MIPS startup (start_<set>.s) and host reference
# main (main_<set>.cpp) for one differential kernel set from its @ABI@
# template. Both generated files list kernels in template order and call
# each with the same six argument triples; neither depends on which ABI
# string differential.cmake later substitutes into the kernel source, so
# ctest never runs this script. Rerun it by hand only when a kernel set
# gains, loses, or renames a kernel, and check the results in.
#
# usage: generate.py <kernels.x.in> <start.s> <main.cpp>

import re
import sys

template, out_s, out_cpp = sys.argv[1:4]
src = open(template).read()
names = re.findall(r"global u32 (k_\w+)\(", src)

# Six argument triples exercising zero/small, mixed, sign-boundary, mixed-hex,
# high-bit, and small-shift-amount inputs. Every kernel is bounded/UB-free
# for each of them (see the family header comments for the ground rules).
ARGS = [
    (0x00000001, 0x00000003, 0x00000005),
    (0x00000007, 0x00000002, 0x00000000),
    (0xffffffff, 0x80000000, 0x7fffffff),
    (0x12345678, 0x9abcdef0, 0x0000002b),
    (0x80000000, 0xffffffff, 0x00000010),
    (0x0000000f, 0x00000010, 0x00000021),
]


def asm_line(line):
    # Directives and labels sit at column 0; mnemonics get one tab, matching
    # the hand-written startup files in test/target/mips/.
    if line.startswith(".") or line.endswith(":"):
        return line
    return "\t" + line


s = [
    ".set noreorder", ".set noat", ".set mips3",
    '.section .text.boot,"ax",@progbits', ".globl _start", ".ent _start", "_start:",
    "lui $sp,0x8080", "addiu $sp,$sp,-64",
    "mfc0 $t0,$12", "lui $t1,0x2000", "or $t0,$t0,$t1", "mtc0 $t0,$12", "nop", "nop",
]
cpp = ['#include <cstdio>', '', 'extern "C" {']
cpp += [f"unsigned {n}(unsigned, unsigned, unsigned);" for n in names]
cpp += ["}", "", "int main() {"]
for n in names:
    for (a, b, c) in ARGS:
        s += [f"li $a0,{a:#x}", f"li $a1,{b:#x}", f"li $a2,{c:#x}", f"jal {n}", "nop",
              "move $a0,$v0", "jal print_hex", "nop"]
        cpp.append(f'    std::printf("%08x\\n", {n}({a:#x}u, {b:#x}u, {c:#x}u)); std::fflush(stdout);')
s += [
    "move $a0,$zero", "addiu $v0,$zero,1", "addiu $t9,$zero,1", ".word 0x7000007f",
    ".Lhalt:", "b .Lhalt", "nop", ".end _start",
    ".ent print_hex", "print_hex:", "lui $t0,0xbf00", "ori $t0,$t0,0x0900",
    "addiu $t1,$zero,8",
    "1:", "srl $t2,$a0,28", "sltiu $t3,$t2,10", "beq $t3,$zero,2f", "nop",
    "addiu $t2,$t2,48", "b 3f", "nop", "2:", "addiu $t2,$t2,87", "3:", "sb $t2,0($t0)",
    "sll $a0,$a0,4", "addiu $t1,$t1,-1", "bne $t1,$zero,1b", "nop",
    "addiu $t2,$zero,10", "sb $t2,0($t0)", "jr $ra", "nop", ".end print_hex",
]
cpp += ["    return 0;", "}"]

header_s = [
    "# Copyright (C) 2026 Cross contributors",
    "# SPDX-License-Identifier: GPL-3.0-or-later",
    "#",
    f"# Generated by generate.py from {template} -- do not edit by hand.",
    "# Calls every kernel in the file with six argument triples and prints",
    "# each u32 result as 8 hex digits over the Malta UART.",
    "",
]
header_cpp = [
    "// Copyright (C) 2026 Cross contributors",
    "// SPDX-License-Identifier: GPL-3.0-or-later",
    "//",
    f"// Generated by generate.py from {template} -- do not edit by hand.",
    "// Host x86-64 reference: prints each u32 result as 8 hex digits, in the",
    "// same kernel/argument order as the generated MIPS startup.",
    "",
]

open(out_s, "w").write("\n".join(header_s + [asm_line(line) for line in s]) + "\n")
open(out_cpp, "w").write("\n".join(header_cpp + cpp) + "\n")
print(f"{len(names)} kernels x {len(ARGS)} argument sets -> {out_s}, {out_cpp}")
